// Builds the two generated files, both committed (test/build.test.js checks they are fresh):
// - src/vendor/openui-lang-core.js: @openuidev/lang-core bundled for the Host, so users'
//   installs neither fetch it nor run its install-telemetry postinstall;
// - src/client/index.js: the Web half (src/client/main.js plus @openuidev/react-lang),
//   wrapped in the client module-loader format. React comes from the page's loader.
// `node scripts/build.mjs [outDir]` writes under outDir (default: the package root).
import { build } from 'esbuild'
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const outDir = process.argv[2] ?? root
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
// Resolve from this package, including dependencies hoisted by npm workspaces.
function version(name) {
  let dir = dirname(fileURLToPath(import.meta.resolve(name)))
  while (true) {
    try {
      const manifest = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'))
      if (manifest.name === name) return manifest.version
    } catch (error) {
      if (error.code !== 'ENOENT') throw error
    }
    const parent = dirname(dir)
    if (parent === dir) throw new Error(`Cannot find package.json for ${name}`)
    dir = parent
  }
}
// Shared with src/quiz/library.js's relative import, so the client bundles one copy.
const VENDOR = join(root, 'src/vendor/openui-lang-core.js')

function write(rel, text) {
  const file = join(outDir, rel)
  mkdirSync(dirname(file), { recursive: true })
  writeFileSync(file, text)
}

async function bundle(options) {
  const result = await build({ absWorkingDir: root, bundle: true, write: false, logLevel: 'warning', legalComments: 'none', charset: 'utf8', ...options })
  // Keep source-label comments identical in standalone and hoisted installs.
  return result.outputFiles[0].text.replace(/^\/\/ (?:\.\.\/)+node_modules\//gm, '// node_modules/')
}

const core = await bundle({
  entryPoints: [fileURLToPath(import.meta.resolve('@openuidev/lang-core'))],
  format: 'esm',
  platform: 'neutral',
  // zod is a runtime dependency of this package; ci-info is only imported when
  // OPENUI_RUNTIME_TELEMETRY_ENABLED opts in, which nothing here does.
  external: ['zod', 'zod/*', 'ci-info'],
})
write('src/vendor/openui-lang-core.js', `// Generated by scripts/build.mjs from @openuidev/lang-core ${version('@openuidev/lang-core')}.
// Copyright (c) 2011-2024 Thesys Inc. MIT License: https://github.com/thesysdev/openui
${core}`)

const ZOD_STUB = `const schema = (type) => new Proxy({ _zod: { def: { type } } }, { get: (t, k) => (k in t ? t[k] : () => schema(type)) })
export const z = new Proxy({}, { get: (_, type) => () => schema(type) })
export const object = () => schema('object')
export const literal = () => schema('literal')
const unavailable = (name) => () => { throw new Error('zod.' + name + ' is not in the learn-anything client build') }
export const clone = unavailable('clone'), registry = unavailable('registry'), toJSONSchema = unavailable('toJSONSchema')
export const util = { mergeDefs: unavailable('util.mergeDefs') }, globalRegistry = { get: unavailable('globalRegistry') }`

// The quiz library's JSON Schema, for the client's Renderer (src/client/quiz.js).
const { ROOT, quizLibrary } = await import(join(root, 'src/quiz/library.js'))
const quizSchema = JSON.stringify({ root: ROOT, jsonSchema: quizLibrary().toJSONSchema() })

const client = await bundle({
  entryPoints: [join(root, 'src/client/main.js')],
  format: 'cjs',
  platform: 'browser',
  target: 'es2022',
  minify: true,
  define: { 'process.env.NODE_ENV': '"production"' },
  external: ['react', 'react-dom', 'react/jsx-runtime'],
  // One copy of lang-core: the one the Host validates quizzes with.
  alias: { '@openuidev/lang-core': VENDOR },
  plugins: [{
    name: 'learn-anything',
    setup(b) {
      // react-lang's development-only devtools auto-mount, dropped by the NODE_ENV define.
      b.onResolve({ filter: /^@openuidev\/devtools$/ }, () => ({ path: 'devtools', external: true }))
      b.onResolve({ filter: /^virtual:quiz-schema$/ }, () => ({ path: 'quiz-schema', namespace: 'virtual' }))
      b.onLoad({ filter: /^quiz-schema$/, namespace: 'virtual' }, () => ({ contents: quizSchema, loader: 'json' }))
      // lang-core builds zod schemas for its built-in functions (@Count, …) at load time;
      // the browser only parses and renders against the JSON Schema above, so a stub that
      // passes defineFunction's checks keeps ~400 KB of zod out of the bundle.
      b.onResolve({ filter: /^zod(\/.*)?$/ }, () => ({ path: 'zod', namespace: 'virtual' }))
      b.onLoad({ filter: /^zod$/, namespace: 'virtual' }, () => ({ contents: ZOD_STUB, loader: 'js' }))
    },
  }],
})
write('src/client/index.js', `// Generated by scripts/build.mjs from src/client/main.js; do not edit. Bundles
// @openuidev/react-lang ${version('@openuidev/react-lang')} and @openuidev/lang-core (MIT, Copyright (c) Thesys Inc.).
window.__ModuleLoader__.load({
id: ${JSON.stringify(pkg.name)},
factory: (require) => {
var module = { exports: {} }
var exports = module.exports
${client}return module.exports
},
})
`)
